<?php
$edit=isset($_GET['edit'])?fetch_one('SELECT * FROM news WHERE id=?',[(int)$_GET['edit']]):null;
$rows=fetch_all('SELECT * FROM news ORDER BY featured DESC,published_at DESC,id DESC');
?>
<div class="split-layout">
<form method="post" enctype="multipart/form-data" class="panel form-panel live-form"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="news_save"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><input type="hidden" name="old_image" value="<?= e($edit['image']??'') ?>"><div class="panel-head"><div><small>İÇERİK MERKEZİ</small><h2><?= $edit?'Haberi düzenle':'Haber veya duyuru oluştur' ?></h2></div><?php if($edit):?><a href="?section=news">Yeni haber +</a><?php endif; ?></div><div class="form-grid"><label class="full">Başlık<input name="title" value="<?= e($edit['title']??'') ?>" data-live="news-title" required></label><label>URL kısa adı<input name="slug" value="<?= e($edit['slug']??'') ?>" placeholder="haber-basligi"></label><label>Yayın tarihi<input type="datetime-local" name="published_at" value="<?= !empty($edit['published_at'])?e(date('Y-m-d\TH:i',strtotime($edit['published_at']))):e(date('Y-m-d\TH:i')) ?>" data-live-date></label><label class="full">Özet<textarea name="summary" data-live="news-summary" maxlength="350"><?= e($edit['summary']??'') ?></textarea><small>Haber kartında gösterilir; 160-220 karakter önerilir.</small></label><label class="full">Haber içeriği<textarea class="editor-area" name="content"><?= e($edit['content']??'') ?></textarea></label><label>Kapak görseli<input type="file" name="image_file" accept="image/jpeg,image/png,image/webp" data-image-preview="news-image"></label><label>Kapak URL<input name="image_url" data-url-preview="news-image" placeholder="https://..."></label><label class="check"><input type="checkbox" name="featured" <?= ($edit['featured']??0)?'checked':'' ?>><span>Öne çıkan haber</span></label><label class="check"><input type="checkbox" name="active" <?= ($edit['active']??1)?'checked':'' ?>><span>Yayında</span></label></div><div class="upload-note"><b>Haber görseli önerisi</b><span>JPG/WEBP, 1600×900 px (16:9), en fazla 5 MB. Aynı görsel sosyal medya paylaşımı